60	}
61	else
62	{
63	    app.UseExceptionHandler("/Error", createScopeForErrors: true);
64	    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
65	    app.UseHsts();
