using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace Gatekeeper.Web.Data;

/// <summary>Applies migrations and seeds a demo admin, tenant, roles and grants on first run.</summary>
public static class DbInitializer
{
    public const string AdminEmail = "admin@gatekeeper.local";
    public const string AdminPassword = "Admin!23456";

    public static async Task InitializeAsync(IServiceProvider services)
    {
        using var scope = services.CreateScope();
        var sp = scope.ServiceProvider;

        var db = sp.GetRequiredService<GatekeeperDbContext>();
        await db.Database.MigrateAsync();

        var userManager = sp.GetRequiredService<UserManager<ApplicationUser>>();

        // Seed a sample tenant so there is something to look at in the console.
        var customer = await db.Customers.FirstOrDefaultAsync(c => c.Name == "Acme Inc");
        if (customer is null)
        {
            customer = new Customer { Name = "Acme Inc", PlanTier = PlanTier.Pro };
            db.Customers.Add(customer);
            await db.SaveChangesAsync();
        }

        // Seed the console admin login.
        var admin = await userManager.FindByEmailAsync(AdminEmail);
        if (admin is null)
        {
            admin = new ApplicationUser
            {
                UserName = AdminEmail,
                Email = AdminEmail,
                EmailConfirmed = true,
                DisplayName = "Console Admin",
                CustomerId = customer.Id,
            };
            await userManager.CreateAsync(admin, AdminPassword);
        }

        // Seed a small role hierarchy and a couple of grants.
        if (!await db.Roles.AnyAsync(r => r.CustomerId == customer.Id))
        {
            var member = new Role
            {
                CustomerId = customer.Id,
                Name = "Member",
                Description = "Base role every user inherits from.",
            };
            var manager = new Role
            {
                CustomerId = customer.Id,
                Name = "Manager",
                Description = "Team managers. Inherits Member.",
                Parent = member,
            };
            db.Roles.AddRange(member, manager);

            db.Grants.AddRange(
                new Grant { CustomerId = customer.Id, Role = member, Effect = GrantEffect.Allow, Permission = "documents.read", Resource = "*" },
                new Grant { CustomerId = customer.Id, Role = manager, Effect = GrantEffect.Allow, Permission = "documents.write", Resource = "*" },
                new Grant { CustomerId = customer.Id, Role = manager, Effect = GrantEffect.Deny, Permission = "billing.manage", Resource = "*" });

            await db.SaveChangesAsync();
        }
    }
}

@page "/audit"
@using Microsoft.EntityFrameworkCore
@attribute [Authorize]
@rendermode @(new InteractiveServerRenderMode(prerender: false))
@inject IDbContextFactory<GatekeeperDbContext> DbFactory

<PageTitle>Gatekeeper · Audit Log</PageTitle>

<h1>Audit Log</h1>
<p class="text-muted">Every change made through the console: who, what, and when. Newest first.</p>

<div class="row g-2 mb-3">
    <div class="col-md-3">
        <input class="form-control" placeholder="Filter by entity type…" @bind="entityFilter" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <input class="form-control" placeholder="Filter by actor…" @bind="actorFilter" @bind:event="oninput" />
    </div>
</div>

@if (entries is null)
{
    <p><em>Loading…</em></p>
}
else
{
    var view = entries
        .Where(e => string.IsNullOrWhiteSpace(entityFilter) || e.EntityType.Contains(entityFilter, StringComparison.OrdinalIgnoreCase))
        .Where(e => string.IsNullOrWhiteSpace(actorFilter) || e.ActorName.Contains(actorFilter, StringComparison.OrdinalIgnoreCase))
        .ToList();

    <p class="text-muted">@view.Count of @entries.Count entries</p>
    <table class="table table-striped table-sm align-middle">
        <thead>
            <tr><th>When</th><th>Actor</th><th>Action</th><th>Entity</th><th>Summary</th></tr>
        </thead>
        <tbody>
            @foreach (var e in view)
            {
                <tr>
                    <td class="text-nowrap">@e.Timestamp.LocalDateTime.ToString("g")</td>
                    <td>@e.ActorName</td>
                    <td><span class="badge @ActionBadge(e.Action)">@e.Action</span></td>
                    <td>@e.EntityType</td>
                    <td>@e.Summary</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<AuditLogEntry>? entries;
    private string entityFilter = string.Empty;
    private string actorFilter = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        entries = await db.AuditLog
            .OrderByDescending(e => e.Timestamp)
            .Take(500)
            .ToListAsync();
    }

    private static string ActionBadge(string action) => action switch
    {
        "Created" => "bg-success",
        "Updated" => "bg-primary",
        "Deleted" => "bg-danger",
        _ => "bg-secondary",
    };
}

